base=target.base;uid=base.uid;sha=base.sha;digest=base.digest;insert=base.insert
original_extension=target.extension
def record(f,value):
 i=f.ids;scope={'organisation_id':i['organisation'],'run_id':i['run']};operation,decision,observation,reason=[uid() for _ in range(4)];owner=f.sql('SELECT a.plan_generation::text,c.cohort_generation::text FROM hyperfide.fleet_actor_sessions a JOIN hyperfide.fleet_cohorts c ON c.id=a.cohort_id WHERE a.session_id=$1',[i['manager']])[0]
 body={'schema_version':1,'kind':'hyperfide.fleet-decision','operation_id':operation,'decision_id':decision,'run_id':i['run'],'actor_id':i['manager'],'actor_role':'WAVE_MANAGER','authority_epoch':i['epoch'],'leader_generation':'1','delegation_id':i['package'],'manager_generation':'2','source_revision':'git:'+f.source,'spec_revision':i['accepted_spec'],'context_digest':sha(operation.encode()),'action':'fleet.install.admit','input':value,'input_digest':digest(value),'expected_version':owner['plan_generation'],'rationale_summary':'Declared component decision input; no model inference or native execution proof'}
 insert(f,'fleet_observations',{**scope,'id':observation,'actor_id':i['manager'],'cohort_generation':int(owner['cohort_generation']),'context_digest':body['context_digest'],'body':{'controlled_fixture_input':True}});insert(f,'fleet_reasoning',{**scope,'id':reason,'actor_id':i['manager'],'request_digest':body['context_digest'],'observation_id':observation,'state':'COMPLETED','result':{'controlled_fixture_input':True}});insert(f,'fleet_decisions',{**scope,'id':decision,'operation_id':operation,'actor_id':i['manager'],'action':'fleet.install.admit','context_digest':body['context_digest'],'payload_digest':digest(body),'reasoning_id':reason,'body':body});return body
def admit(f,value):
 decision=record(f,value);response=f.invoke('fleet.install.admit',{'decision':decision},key='manager',component='fleet-install')[1];return decision,response
def lineage(f,admission,root,epoch,failed):
 i=f.ids;principal=next(p for p in json.loads(f.identity_config.read_text())['principals'] if p['credential_id']==i['operator']);data={'scope':{'organisation_id':i['organisation'],'run_id':i['run']},'principal':principal,'operation':admission['operation_id'],'root':root,'epoch':epoch,'failed':failed,'authority_epoch':i['epoch']}
 script=r"""
import fs from'node:fs';import{createResourceContainer}from'./core/control-plane/dist/storage/runtime.js';import{authenticatedInvocation}from'./core/control-plane/dist/transport/protocol.js';import{readBootstrapInstallAllocationEpoch}from'./core/control-plane/dist/preparation/fleet_install_lineage.js';import{fleetInstallDeliveryInputs}from'./core/control-plane/dist/preparation/fleet_authority.js';import{bootstrapInstallAllocationRequestId}from'./core/control-plane/dist/providers/bootstrap_install.js';
const d=JSON.parse(fs.readFileSync(0)),r=createResourceContainer({role:'control',env:process.env,signal:new AbortController().signal}),assert=(v,m)=>{if(!v)throw Error(m)},i=authenticatedInvocation({principal:d.principal,signal:new AbortController().signal,guard:async t=>{const row=(await t.query('SELECT authority_epoch FROM hyperfide.runs WHERE organisation_id=$1 AND id=$2',[d.scope.organisation_id,d.scope.run_id])).rows[0];assert(row?.authority_epoch===d.authority_epoch,'Current authority required')}});
try{const result=await r.gateway.withPrimaryTransaction({guard:i.guard},async tx=>{const found=await readBootstrapInstallAllocationEpoch(tx,{...d.scope,operation_id:d.operation}),delivery=await fleetInstallDeliveryInputs(tx,i,d.operation);assert(found.logical_operation_id===d.root&&found.allocation_epoch_operation_id===d.epoch,'Mixed recovery allocation epoch/root mismatch');assert(delivery.logical_operation_id===d.root&&delivery.allocation_epoch_operation_id===d.epoch&&delivery.admission.logical_operation_id===d.epoch&&Object.hasOwn(delivery.admission,'recovery_of')===d.failed,'Native/coordinator lineage conflated');const identity={bootstrap_id:d.root,descriptor_digest:'sha256:'+'a'.repeat(64),input_digest:delivery.admission.input_digest,purpose:'preparation',task_id:d.root};assert(bootstrapInstallAllocationRequestId({...identity,execution_operation_id:found.allocation_epoch_operation_id})===bootstrapInstallAllocationRequestId({...identity,execution_operation_id:d.epoch}),'Allocation did not use nearest never-started epoch');assert(bootstrapInstallAllocationRequestId({...identity,execution_operation_id:d.root})!==bootstrapInstallAllocationRequestId({...identity,execution_operation_id:d.epoch}),'Expired root allocation identity reused');return found});console.log(JSON.stringify({status:'PASS',scope:'actual PostgreSQL production mixed lineage/delivery inputs and epoch-based allocation identity',result}));}finally{await r.close()}
"""
 p=subprocess.run(['node','--input-type=module','-e',script],input=json.dumps(data),text=True,capture_output=True,cwd=ROOT,env=f.env,timeout=30);print(p.stdout,end='');print(p.stderr,end='',file=sys.stderr);assert p.returncode==0

def extension(f,decision,n):
 original_extension(f,decision,n)
 i=f.ids;scope={'organisation_id':i['organisation'],'run_id':i['run']};common=[i['organisation'],i['run']];root=f.sql('SELECT logical_operation_id::text FROM hyperfide.fleet_install_heads WHERE current_operation_id=$1',[n['operation_id']])[0]['logical_operation_id'];aux=f.sql('SELECT * FROM hyperfide.fleet_install_delivery_executions WHERE operation_id=$1',[n['operation_id']])[0];b=aux['target_binding'];allocation=f.sql('SELECT * FROM hyperfide.resource_job_allocations WHERE id=$1',[b['allocation_id']])[0];expires=f.sql('SELECT expires_at::text FROM hyperfide.reservations WHERE id=$1',[b['reservation_id']])[0]['expires_at']
 plan={'operation_id':n['operation_id'],'binding':{'sandbox_id':i['sandbox'],'boot_id':i['boot'],'boot_generation':'1','session_id':b['session_id'],'slot_id':b['slot_id']},'allocation':{'allocation_id':allocation['id'],'request_id':allocation['request_id'],'generation':str(allocation['generation'])},'preparation_request':{'job_binding':{'namespace':'FLEET_INSTALL','job_id':n['operation_id'],'input_packet_digest':n['admission_digest']}}};plan_digest=digest(plan);quiescence=sha(b'CONTROLLED_HISTORICAL_FAILED_QUIESCENCE_INPUT');result={**scope,'operation_id':n['operation_id'],'session_id':b['session_id'],'fixture':'CONTROLLED_HISTORICAL_FAILED_INPUT_NOT_NATIVE_EXECUTION_PROOF','outcome':'FAILED','cleanup_status':'CONFIRMED','cleanup':{'complete':True,'observed_process_absent':True,'receipt_digest':quiescence},'native_receipt':{'digest':quiescence}};result_digest=digest(result)
 signature=f.sign('provisioner',('HYPERFIDE-RUNNER-RESULT-V1\n'+i['organisation']+'\n'+i['run']+'\n'+n['operation_id']+'\n'+plan_digest+'\n'+result_digest+'\n').encode())
 insert(f,'runner_remote_jobs',{**scope,'operation_id':n['operation_id'],'session_id':b['session_id'],'job_class':'PREPARATION','plan':plan,'plan_digest':plan_digest,'principal':{'controlled_historical_failed_input':True},'admission_digest':n['admission_digest'],'authority_epoch':i['epoch'],'reservation_id':b['reservation_id'],'expires_at':expires})
 f.sql("UPDATE hyperfide.runner_remote_jobs SET state='CLAIMED',claim_id=$2,executor_credential_id=$3,claimed_at=clock_timestamp() WHERE operation_id=$1",[n['operation_id'],uid(),i['provisioner']]);f.sql("UPDATE hyperfide.runner_remote_jobs SET state='COMPLETED',result=$2,result_digest=$3,result_signature=$4,completed_at=clock_timestamp() WHERE operation_id=$1",[n['operation_id'],json.dumps(result),result_digest,signature])
 artifact=uid();insert(f,'artifacts',{**scope,'id':artifact,'digest':quiescence,'size_bytes':0,'storage_backend':'CONTROLLED_HISTORICAL_METADATA_ONLY','storage_key':artifact,'status':'COMPLETE'});insert(f,'runner_result_artifacts',{**scope,'operation_id':n['operation_id'],'role':'native_receipt','artifact_id':artifact,'artifact_digest':quiescence,'content_digest':quiescence,'size_bytes':0})
 recovery={'install_operation_id':n['operation_id'],'admission_digest':n['admission_digest'],'runner_operation_id':n['operation_id'],'runner_plan_digest':plan_digest,'quiescence_operation_id':n['operation_id'],'quiescence_receipt_digest':quiescence};value=copy.deepcopy(decision['input']);value['recovery_of']=recovery;value['ttl_seconds']=10;fd,answer=admit(f,value);assert answer.get('ok'),answer;failed=answer['result']['admission'];assert failed['logical_operation_id']==n['operation_id'] and failed['recovery_of']==recovery,failed
 lineage(f,failed,root,n['operation_id'],True)
 response=f.ok('fleet.install.delivery.collect',{'operation_id':failed['operation_id']},key='operator',component='fleet-install-delivery');assert response['state']=='PENDING',response
 row=f.sql('SELECT * FROM hyperfide.fleet_install_delivery_executions WHERE operation_id=$1',[failed['operation_id']])[0];assert row['logical_operation_id']==root and row['target_binding']==b,'FAILED successor reused expired root target or changed current epoch'
 print(json.dumps({'status':'PASS','scope':'actual signed FAILED recovery admission/delivery mapping with explicitly controlled signed historical FAILED input; no native execution','global_root_preserved':True,'nearest_not_started_target_preserved':True}),flush=True)
 # A mixed FAILED ancestor cannot be erased by calling a shared-reservation successor NOT_STARTED.
 fp={'operation_id':failed['operation_id'],'binding':plan['binding'],'allocation':plan['allocation'],'preparation_request':{'job_binding':{'namespace':'FLEET_INSTALL','job_id':failed['operation_id'],'input_packet_digest':failed['admission_digest']}}};fp_digest=digest(fp)
 insert(f,'runner_remote_jobs',{**scope,'operation_id':failed['operation_id'],'session_id':b['session_id'],'job_class':'PREPARATION','plan':fp,'plan_digest':fp_digest,'principal':{'controlled_never_submitted_successor_input':True},'admission_digest':failed['admission_digest'],'authority_epoch':i['epoch'],'reservation_id':b['reservation_id'],'expires_at':failed['expires_at']})
 deadline=time.monotonic()+15
 while not f.sql('SELECT expires_at<=clock_timestamp() AS expired FROM hyperfide.fleet_environment_installs WHERE operation_id=$1',[failed['operation_id']])[0]['expired']:
  assert time.monotonic()<deadline,'Actual database expiry did not arrive';time.sleep(.1)
 candidate=copy.deepcopy(value);candidate['recovery_of']={'kind':'NOT_STARTED','install_operation_id':failed['operation_id'],'admission_digest':failed['admission_digest'],'runner_operation_id':failed['operation_id'],'runner_plan_digest':fp_digest};candidate['ttl_seconds']=300
 before=f.sql('SELECT to_jsonb(r) AS row FROM hyperfide.reservations r WHERE request_id=$1 ORDER BY id',[b['request_id']]);_,refused=admit(f,candidate);assert refused.get('error',{}).get('code')=='FLEET_INSTALL_NOT_STARTED_UNPROVEN',refused
 assert f.sql('SELECT to_jsonb(r) AS row FROM hyperfide.reservations r WHERE request_id=$1 ORDER BY id',[b['request_id']])==before,'Unproven mixed successor released capacity';assert not f.sql('SELECT id FROM hyperfide.runner_not_started_proofs WHERE install_operation_id=$1',[failed['operation_id']])
 print(json.dumps({'status':'PASS','scope':'actual expired mixed successor NOT_STARTED refusal preserves current allocation and prior FAILED history; no filesystem-reset inference'}),flush=True)
def main():
 if not os.environ.get('DATABASE_URL'):return subprocess.run([sys.executable,str(ROOT/'tests/hyperfide/support/withpg.py'),'--',sys.executable,str(Path(__file__).resolve())],cwd=ROOT).returncode
